from taf.internal.gnb.oam.coam.vdu.client.emservice_licensed.v1 import (
    ApiClient,
    ApiException,
    ClientType,
    Configuration,
    M2mEmservicePEApi,
    M2mEmserviceStatusApi,
)

from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.emservice_licensed.http_client import EMServiceLicensedv1HttpClient
from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.m2m_interface_availability_checker import (
    m2m_interface_availability_check,
)
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage


@auto_token_refresh(api_exception=ApiException)
class EMServiceLicensedv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.em_service_status_api = M2mEmserviceStatusApi(api_client=api_client)
        self.em_service_pe_api = M2mEmservicePEApi(api_client=api_client)
        self.local_client = EMServiceLicensedv1HttpClient(base_url=con_details.base_url,
                                                          connection_alias=con_details.alias)
        client_type = ClientType()
        self.accepted_client_types = {'em': client_type.EM,
                                      'nms': client_type.NMS,
                                      'internal': client_type.INTERNAL,
                                      'smo': client_type.SMO}

    @m2m_interface_availability_check
    def get_nms(self, timeout=30):
        return self.em_service_status_api.m2m_get_nms(_request_timeout=timeout)

    @m2m_interface_availability_check
    def activate_pre_activated_plan(self, plan_id, timeout=30):
        x_oam_client_type = self.accepted_client_types['em']
        activated_res = self.em_service_pe_api.plans_plan_id_operations_activations_post(x_oam_client_type=x_oam_client_type,
                                                                                      plan_id=plan_id,
                                                                                      _request_timeout=timeout)
        return activated_res.id

    @m2m_interface_availability_check
    def get_activated_operation_status(self, plan_id, operation_id, timeout=30):
        res = self.em_service_pe_api.get_activation(plan_id=plan_id, operation_id=operation_id, _request_timeout=timeout)
        return res.is_completed

    @m2m_interface_availability_check
    def get_activated_operation_detail_status(self, plan_id, operation_id, timeout=30):
        return self.local_client.get_activated_operation_detail_status(plan_id=plan_id, operation_id=operation_id,
                                                                       timeout=timeout)
